import { Bedrock } from "@techgoose-labs/bedrock";
import { Frontend } from "@techgoose-labs/sprig/bedrock";
import { fromFileUrl } from "@std/path";
import { api } from "./bootstrap/mod.ts";
import { sprigApp } from "./src/mod.ts";

// UI-at-root layout (src/ + static/ beside this file, no ui/ package): Frontend() only
// derives <root>/ui|app/{src,static}, so the composed app and its built assets are passed.
export default Bedrock({
  ui: Frontend({
    app: sprigApp,
    assetsDir: fromFileUrl(new URL("./static", import.meta.url)),
  }),
  backend: api,
});
